--[[
  M0$$AD / EXTERNAL PANEL V5.2.1
  GUI library (Luau) for a fictional RP launcher.
  This file renders interface only: it does not bypass protections,
  inject into games or modify game state.

  For asset support in third-party Lua environments:
     readfile / writefile / makefolder / getcustomasset or getsynasset
  Official Roblox Studio does NOT offer these functions. Use
  published Roblox image asset IDs in Studio instead.
]]

local UI = { VERSION = '5.2.1' }
local Players = game:GetService('Players')
local TweenService = game:GetService('TweenService')
local UserInputService = game:GetService('UserInputService')
local ContentProvider = game:GetService('ContentProvider')

local PALETTE = {
    Back = Color3.fromRGB(5, 9, 18),
    Panel = Color3.fromRGB(5, 9, 17),
    Row = Color3.fromRGB(9, 13, 21),
    RowHover = Color3.fromRGB(15, 30, 53),
    RowActive = Color3.fromRGB(16, 48, 91),
    Edge = Color3.fromRGB(22, 65, 103),
    Accent = Color3.fromRGB(50, 148, 246),
    AccentPale = Color3.fromRGB(150, 205, 255),
    White = Color3.fromRGB(241, 246, 255),
    Secondary = Color3.fromRGB(159, 171, 191),
    Dim = Color3.fromRGB(138, 159, 186),
    Success = Color3.fromRGB(119, 217, 174),
    Error = Color3.fromRGB(241, 135, 144),
}

local function create(className, props, parent)
    local item = Instance.new(className)
    for key, value in pairs(props or {}) do
        item[key] = value
    end
    if parent then item.Parent = parent end
    return item
end
local function text(parent, caption, x, y, w, h, size, weight, color, z)
    return create('TextLabel', {
        BackgroundTransparency=1,
        Position=UDim2.fromOffset(x, y), Size=UDim2.fromOffset(w,h),
        Font=weight == 'bold' and Enum.Font.GothamBold or Enum.Font.GothamMedium,
        Text=tostring(caption), TextColor3=color or PALETTE.White,
        TextSize=size, TextXAlignment=Enum.TextXAlignment.Left,
        TextYAlignment=Enum.TextYAlignment.Center,
        TextTruncate=Enum.TextTruncate.AtEnd,
        ZIndex=z or 8,
    }, parent)
end
local function corner(item, n)
    return create('UICorner', {CornerRadius=UDim.new(0,n)},item)
end
local function stroke(item, c, alpha, thick)
    return create('UIStroke', {
        Color=c,Transparency=alpha or 0,
        Thickness=thick or 1,
        ApplyStrokeMode=Enum.ApplyStrokeMode.Border,
    },item)
end
local function gradient(item, a, b, degrees)
    return create('UIGradient', {
        Rotation=degrees or 90,
        Color=ColorSequence.new({ColorSequenceKeypoint.new(0,a),ColorSequenceKeypoint.new(1,b)})
    },item)
end
local function animate(item, seconds, props)
    if not item or not item.Parent then return end
    local job=TweenService:Create(item, TweenInfo.new(seconds or .14,Enum.EasingStyle.Quad,Enum.EasingDirection.Out),props)
    job:Play()
    return job
end
local function getGuiParent()
    if type(gethui)=='function' then
        local ok, result=pcall(gethui)
        if ok and typeof(result)=='Instance' then return result end
    end
    local player=Players.LocalPlayer
    return player and player:WaitForChild('PlayerGui') or game:GetService('CoreGui')
end

