local function base64decode(s)
    if type(s)~='string' then return nil end
    local alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
    local lookup={}
    for i=1,#alphabet do lookup[alphabet:sub(i,i)]=i-1 end
    local accumulated,nbits=0,0
    local output={}
    for i=1,#s do
        local n=lookup[s:sub(i,i)]
        if n then
            accumulated=accumulated*64+n
            nbits=nbits+6
            if nbits>=8 then
                nbits=nbits-8
                local divisor=2^nbits
                output[#output+1]=string.char(math.floor(accumulated/divisor))
                accumulated=accumulated%divisor
            end
        end
    end
    return table.concat(output)
end
local function isPng(contents)
    return type(contents)=='string' and #contents>75 and #contents<5000000
        and contents:sub(1,8)=='\137PNG\r\n\26\n'
end
local Asset = {}
Asset.__index=Asset
function Asset.new(base,version)
    local self=setmetatable({},Asset)
    self.base=tostring(base or ''):gsub('/+$','')
    self.dir='M0SSAD_UI/assets/'..tostring(version or 'v5_2_m0ssad_bypasser'):gsub('[^%w_-]','')
    self.request=(syn and syn.request) or http_request or request
        or (fluxus and fluxus.request) or (krnl and krnl.request)
    self.custom=(type(getcustomasset)=='function' and getcustomasset)
        or (type(getsynasset)=='function' and getsynasset)
    self.loaded={}
    return self
end
function Asset:ensureFolders()
    if type(makefolder)~='function' then return false end
    for _,folder in ipairs({'M0SSAD_UI','M0SSAD_UI/assets',self.dir}) do
        local exists=false
        if type(isfolder)=='function' then
            local ok,found=pcall(isfolder,folder)
            exists=ok and found
        end
        if not exists then
            local ok=pcall(makefolder,folder)
            if not ok then return false end
        end
    end
    return true
end
function Asset:download(file)
    if not self.base:match('^https://raw%.githubusercontent%.com/') then return nil end
    local url=self.base..'/'..file
    if self.request then
        local ok,res=pcall(self.request,{Url=url,Method='GET',Headers={Accept='image/png'}})
        if ok and type(res)=='table' then
            local status=tonumber(res.StatusCode or res.status_code or 0) or 0
            local content=res.Body or res.body
            if status>=200 and status<300 and isPng(content) then return content end
        end
    end
    local ok,content=pcall(function()return game:HttpGet(url)end)
    if ok and isPng(content) then return content end
    return nil
end
function Asset:load(name)
    if self.loaded[name] then return self.loaded[name] end
    if not tostring(name):match('^[%w_-]+%.png$') then return nil end
    if not self.custom or type(writefile)~='function' or not self:ensureFolders() then return nil end
    local path=self.dir..'/'..name
    local content
    if type(readfile)=='function' then
        local ok,contents=pcall(readfile,path)
        if ok and isPng(contents) then content=contents end
    end
    if not content then
        content=self:download(name)
        if not isPng(content) and BUNDLED_PNG[name] then
            content=base64decode(BUNDLED_PNG[name])
        end
        if not isPng(content) then warn('[M0$$AD] Image introuvable: '..name);return nil end
        if not pcall(writefile,path,content) then return nil end
    end
    local ok,asset=pcall(self.custom,path)
    if ok and type(asset)=='string' and #asset>0 then
        self.loaded[name]=asset
        return asset
    end
    return nil
end

