function UI.new(config)
    config=config or {}
    local guiParent=getGuiParent()
    -- Re-running the loader removes the previous UI and its hotkey listener.
    local globalEnv = (type(getgenv) == 'function' and getgenv()) or _G
    -- Clean up V5.1 too, to avoid two panels on a hot reload.
    for _,cleanup in ipairs({'M0SSAD_UI_Cleanup','NexusRP_UI_Cleanup'}) do
        if type(globalEnv[cleanup]) == 'function' then pcall(globalEnv[cleanup]) end
    end
    for _,oldName in ipairs({'M0SSADLauncherV52','NexusExternalCyberV5'}) do
        local old=guiParent:FindFirstChild(oldName)
        if old then old:Destroy() end
    end

    local loader=Asset.new(config.AssetBaseURL,config.CacheVersion or 'v5_2_m0ssad_bypasser')
    local games=config.Games or DEFAULT_GAMES
    local alive, busy, selected=true,false,nil
