    local function fitToScreen()
        local camera=workspace.CurrentCamera
        local v=camera and camera.ViewportSize or Vector2.new(1280,720)
        scale.Scale=math.clamp(math.min(1,(v.X-30)/panelWidth,(v.Y-30)/panelHeight),.42,1)
    end
    fitToScreen()
    local function connectCamera()
        local camera=workspace.CurrentCamera
        if camera then table.insert(connections,camera:GetPropertyChangedSignal('ViewportSize'):Connect(fitToScreen)) end
