    keyHint.TextYAlignment=Enum.TextYAlignment.Top

    -- The binding is local to this UI. Save it when the environment supports
    -- persistent files, but still work normally without those functions.
    local keyPath='M0SSAD_UI/menu_toggle_key.txt'
    local function resolveKey(value)
        if typeof(value)=='EnumItem' then
            if value.EnumType==Enum.KeyCode and value~=Enum.KeyCode.Unknown
                and value~=Enum.KeyCode.Escape then return value end
            return nil
        end
        if type(value)~='string' then return nil end
        local ok,key=pcall(function() return Enum.KeyCode[value] end)
        if ok and key and key~=Enum.KeyCode.Unknown and key~=Enum.KeyCode.Escape then
            return key
        end
        return nil
    end
    local toggleKey=resolveKey(config.Keybind) or Enum.KeyCode.RightShift
    if type(readfile)=='function' then
        local ok,saved=pcall(readfile,keyPath)
        if ok then
            toggleKey=resolveKey(tostring(saved)) or toggleKey
        else
            -- Preserve the user's hotkey from the previous Nexus version.
            local legacyOK,legacy=pcall(readfile,'NexusUI/menu_toggle_key.txt')
            if legacyOK then toggleKey=resolveKey(tostring(legacy)) or toggleKey end
        end
    end
    local capturing=false
    local function prettyKey(key)
        return key.Name:gsub('(%l)(%u)','%1 %2')
    end
    local function saveKey(key)
        if type(writefile)~='function' then return end
        if type(makefolder)=='function' then pcall(makefolder,'M0SSAD_UI') end
        pcall(writefile,keyPath,key.Name)
    end
    keyButton.Text=prettyKey(toggleKey)
    keyButton.MouseButton1Click:Connect(function()
        if not alive then return end
        capturing=true
        keyButton.Text='PRESS KEY...'
        keyHint.Text='Appuie sur une touche (Échap pour annuler).'
    end)

    -- Minimal bottom status strip, no counters, badges or pointless ornaments.
    local footer=create('Frame',{
        Name='Footer',Position=UDim2.fromOffset(0,461),Size=UDim2.fromOffset(panelWidth,36),
        BackgroundColor3=Color3.fromRGB(4,9,16),BorderSizePixel=0,ZIndex=8,
    },window)
    create('Frame',{
        Position=UDim2.fromOffset(0,0),Size=UDim2.fromOffset(panelWidth,1),
        BackgroundColor3=Color3.fromRGB(30,80,130),BackgroundTransparency=.15,
        BorderSizePixel=0,ZIndex=9,
    },footer)
    local status=text(footer,'READY',17,7,231,22,12,'bold',PALETTE.Secondary,9)
    local version=text(footer,'M0$$AD  /  V5.2',215,7,146,22,11,'bold',PALETTE.Secondary,9)
    version.TextXAlignment=Enum.TextXAlignment.Right

    local self={Gui=gui,Window=root,Scene=backdrop}
    function self:GetKeybind()
        return toggleKey
    end
    function self:SetKeybind(value)
        local nextKey=resolveKey(value)
        if not alive or not nextKey then return false end
        toggleKey=nextKey
        capturing=false
        keyButton.Text=prettyKey(toggleKey)
        keyHint.Text='Clique sur la touche, puis appuie sur une nouvelle touche.'
        saveKey(toggleKey)
        return true
    end

    local function loadArt(node,filename,whenLoaded)
        task.spawn(function()
            local id=loader:load(filename)
            if not id or not alive or not node.Parent then return end
            node.Image=id
            pcall(function()ContentProvider:PreloadAsync({node})end)
            if not alive or not node.Parent then return end
            node.ImageTransparency=0
            if whenLoaded then whenLoaded() end
        end)
    end
    loadArt(shadowImage,'panel_shadow.png',function()shadowFallback.Visible=false end)
    loadArt(surface,'panel_surface.png')
    loadArt(hero,config.HeaderFile or 'hero_m0ssad_bypasser.png',function()heroFallback.Visible=false end)
    loadArt(actionImage,'launch_btn.png')

    local currentTab='games'
    function self:SetTab(value)
        if not alive then return end
        currentTab=(value=='config') and 'config' or 'games'
        gamesPage.Visible=currentTab=='games'
        settingsPage.Visible=currentTab=='config'
        animate(activeLine,.18,{Position=UDim2.fromOffset(currentTab=='games' and 0 or panelWidth/2,34)})
        animate(tabGames,.14,{TextColor3=currentTab=='games' and PALETTE.AccentPale or PALETTE.Dim})
        animate(tabConfig,.14,{TextColor3=currentTab=='config' and PALETTE.AccentPale or PALETTE.Dim})
    end
    tabGames.MouseButton1Click:Connect(function()self:SetTab('games')end)
    tabConfig.MouseButton1Click:Connect(function()self:SetTab('config')end)

    local function refresh()
        for _,r in ipairs(rows) do
            local active=r.game==selected
            r.selected.Visible=active
            animate(r.base,.14,{BackgroundColor3=active and PALETTE.RowActive or PALETTE.Row})
            r.edge.Transparency=active and .4 or .82
            r.text.TextColor3=active and PALETTE.White or Color3.fromRGB(218,227,239)
            r.suffix.TextColor3=active and PALETTE.AccentPale or PALETTE.Dim
        end
    end
    local function filterGames()
        local query=string.lower(searchBox.Text):gsub('^%s+',''):gsub('%s+$','')
        local visibleCount,firstMatch=0,nil
        local selectedVisible=false
        for _,r in ipairs(rows) do
            local matches=query=='' or string.find(string.lower(r.game.Name),query,1,true)~=nil
            r.root.Visible=matches
            if matches then
                visibleCount=visibleCount+1
                firstMatch=firstMatch or r.game
                if r.game==selected then selectedVisible=true end
            end
        end
        if not selectedVisible then selected=firstMatch end
        emptySearch.Visible=visibleCount==0
        gameList.CanvasSize=UDim2.fromOffset(0,math.max(0,visibleCount*42-5))
        gameList.CanvasPosition=Vector2.new(0,0)
        refresh()
    end
    function self:SearchGames(query)
        if not alive then return end
        searchBox.Text=tostring(query or '')
        filterGames()
    end
    function self:GetSelection()
        return selected and selected.Name or nil
    end
    function self:SetStatus(message,kind)
        status.Text=tostring(message or 'READY')
        local color=PALETTE.Secondary
        if kind=='success' then color=PALETTE.Success
        elseif kind=='error' then color=PALETTE.Error
        elseif kind=='loading' then color=PALETTE.AccentPale end
        status.TextColor3=color
    end
    function self:SelectGame(name)
        for _,g in ipairs(games) do
            if g.Name==name then
                selected=g;refresh()
                if type(config.OnSelect)=='function' then
                    task.spawn(function()pcall(config.OnSelect,name,self)end)
                end
                return true
            end
        end
        return false
    end
    local function addRow(g,index)
        local row=create('TextButton',{
            Name='Game'..index,LayoutOrder=index,Size=UDim2.new(1,0,0,37),
            Text='',BackgroundTransparency=1,AutoButtonColor=false,ZIndex=8,
        },gameList)
        local base=create('Frame',{
            Size=UDim2.fromScale(1,1),BackgroundColor3=PALETTE.Row,
            BorderSizePixel=0,ZIndex=8,
        },row)
        local edge=stroke(base,PALETTE.Edge,.82,1)
        local highlighted=create('ImageLabel',{
            Name='ActiveRowArt',Size=UDim2.fromScale(1,1),
            BackgroundTransparency=1,Image='',ImageTransparency=1,
            Visible=false,ScaleType=Enum.ScaleType.Stretch,ZIndex=9,
        },base)
        -- Small icons with no surrounding 'AI-looking' rounded badges.
        local ico=create('ImageLabel',{
            Name='GameIcon',Position=UDim2.fromOffset(10,5),Size=UDim2.fromOffset(27,27),
            Image='',ImageTransparency=1,BackgroundTransparency=1,
            ScaleType=Enum.ScaleType.Fit,ZIndex=10,
        },base)
        local fallback=text(base,tostring(g.Initial or g.Name:sub(1,1)),10,5,27,27,15,'bold',PALETTE.AccentPale,9)
        fallback.TextXAlignment=Enum.TextXAlignment.Center
        local name=text(base,g.Name,49,0,249,37,14,'medium',PALETTE.White,10)
        local suffix=text(base,'↗',310,0,25,37,16,nil,PALETTE.Secondary,10)
        suffix.TextXAlignment=Enum.TextXAlignment.Center
        local r={game=g,root=row,base=base,edge=edge,selected=highlighted,text=name,suffix=suffix}
        rows[#rows+1]=r
        loadArt(highlighted,'selected_row.png')
        if g.Icon then loadArt(ico,g.Icon,function()fallback.Visible=false end) end
        row.MouseEnter:Connect(function()
            if alive and not busy and g~=selected then
                animate(base,.12,{BackgroundColor3=PALETTE.RowHover})
            end
        end)
        row.MouseLeave:Connect(function()
            if alive and g~=selected then
                animate(base,.12,{BackgroundColor3=PALETTE.Row})
            end
        end)
        row.MouseButton1Click:Connect(function()
            if alive and not busy then self:SelectGame(g.Name) end
        end)
    end
    function self:SetGames(list)
        if not alive then return end
        for _,r in ipairs(rows) do r.root:Destroy() end
        table.clear(rows)
        games=list or {}
        selected=games[1]
        for i,g in ipairs(games) do addRow(g,i) end
        filterGames()
    end
    self:SetGames(games)
    self:SetStatus("Inactif")
    searchBox:GetPropertyChangedSignal('Text'):Connect(filterGames)

    actionButton.MouseEnter:Connect(function()
        if alive and not busy then
            animate(actionFrame,.12,{BackgroundColor3=Color3.fromRGB(22,108,212)})
            animate(actionTitle,.12,{TextColor3=Color3.fromRGB(255,255,255)})
        end
    end)
    actionButton.MouseLeave:Connect(function()
        if alive then
            animate(actionFrame,.12,{BackgroundColor3=Color3.fromRGB(17,76,144)})
            animate(actionTitle,.12,{TextColor3=PALETTE.White})
        end
    end)
    actionButton.MouseButton1Click:Connect(function()
        if not alive or busy then return end
        if not selected then self:SetStatus('SELECT A GAME','error');return end
        busy=true
        local chosen=selected.Name
        self:SetStatus('SIMULATING  •  '..chosen,'loading')
        actionTitle.Text='PLEASE WAIT...'
        task.spawn(function()
            local ok=true
            if type(config.OnLaunch)=='function' then
                local success,err=pcall(config.OnLaunch,chosen,self)
                ok=success
                if not success then warn('[M0$$AD] RP callback: '..tostring(err)) end
            else
                task.wait(.85)
            end
            if alive then
                busy=false
                actionTitle.Text=tostring(config.ButtonText or 'LANCER LE BYPASS')
                self:SetStatus(     ok and "Actif" or "Inactif",     ok and "success" or nil )
            end
        end)
    end)

    -- Drag only by banner, not the whole screen.
    local dragging=false
    local dragStart,startPosition
    local dragControl=create('TextButton',{
        Name='DragHeader',Position=UDim2.fromOffset(0,0),Size=UDim2.fromOffset(panelWidth-32,108),
        Text='',AutoButtonColor=false,BackgroundTransparency=1,ZIndex=9,
    },window)
    dragControl.InputBegan:Connect(function(input)
        if input.UserInputType==Enum.UserInputType.MouseButton1
            or input.UserInputType==Enum.UserInputType.Touch then
            dragging=true
            dragStart=input.Position
            startPosition=root.Position
        end
    end)
    table.insert(connections,UserInputService.InputChanged:Connect(function(input)
        if not dragging then return end
        if input.UserInputType~=Enum.UserInputType.MouseMovement and input.UserInputType~=Enum.UserInputType.Touch then return end
        local delta=input.Position-dragStart
        root.Position=UDim2.new(startPosition.X.Scale,startPosition.X.Offset+delta.X/scale.Scale,
            startPosition.Y.Scale,startPosition.Y.Offset+delta.Y/scale.Scale)
    end))
    table.insert(connections,UserInputService.InputEnded:Connect(function(input)
        if input.UserInputType==Enum.UserInputType.MouseButton1
            or input.UserInputType==Enum.UserInputType.Touch then dragging=false end
    end))
    close.MouseEnter:Connect(function()animate(close,.12,{TextColor3=PALETTE.White})end)
    close.MouseLeave:Connect(function()animate(close,.12,{TextColor3=Color3.fromRGB(147,173,207)})end)

    function self:SetBackgroundVisible(yes)
        sceneEnabled=yes==true
        backdrop.Visible=sceneEnabled and root.Visible
    end
    function self:Show()
        if not alive then return end
        root.Visible=true
        backdrop.Visible=sceneEnabled
    end
    function self:Hide()
        if not alive then return end
        root.Visible=false
        backdrop.Visible=false
        if searchBox:IsFocused() then searchBox:ReleaseFocus() end
        capturing=false
        keyButton.Text=prettyKey(toggleKey)
    end
    function self:Toggle()
        if not alive then return end
        if root.Visible then self:Hide() else self:Show() end
    end
    function self:Destroy()
        if not alive then return end
        alive=false
        for _,conn in ipairs(connections) do conn:Disconnect() end
        if globalEnv.M0SSAD_UI_Cleanup then
            globalEnv.M0SSAD_UI_Cleanup=nil
        end
        gui:Destroy()
    end
    globalEnv.M0SSAD_UI_Cleanup=function() self:Destroy() end

    -- When capturing a key, keyboard input updates the binding instead of
    -- triggering show/hide; typing into search never hides the UI.
    table.insert(connections,UserInputService.InputBegan:Connect(function(input,processed)
        if not alive or input.UserInputType~=Enum.UserInputType.Keyboard then return end
        if capturing then
            if input.KeyCode==Enum.KeyCode.Escape then
                capturing=false
                keyButton.Text=prettyKey(toggleKey)
                keyHint.Text='Modification annulée.'
            else
                self:SetKeybind(input.KeyCode)
            end
            return
        end
        if processed or UserInputService:GetFocusedTextBox() then return end
        if input.KeyCode==toggleKey then self:Toggle() end
    end))
    -- The X just hides the window; the configured shortcut brings it back.
    close.MouseButton1Click:Connect(function()self:Hide()end)
    return self
end
UI.Create=UI.new
return UI
